SELECT DISTINCT a.user_id, a.DEPT_ID as org_id, a.PHONENUMBER as mobile_phone, a.tenant_id, min(rel.role_id) as 'roleId' FROM sys_user a LEFT JOIN sys_user_role rel ON a.user_id = rel.user_id WHERE a.del_flag = '0' AND a.tenant_id in
#{item.tenantId}
and rel.role_id in ('2','4') GROUP BY a.user_id

SELECT t2.user_id, GROUP_CONCAT( t1.DEPT_ID) as 'parentOrgIdStr' FROM sys_user t2 LEFT JOIN sys_dept t1 ON t1.tenant_id = t2.tenant_id WHERE t2.DEL_FLAG = '0'
AND(
(t2.user_id = #{item.userId} AND t1.dept_id IN
#{item1}
)
)
GROUP BY t2.user_id

SELECT DISTINCT a.user_id, a.DEPT_ID as org_id, a.PHONENUMBER as mobile_phone, a.tenant_id, case when min(rel.role_id)='2' then '2' else '4' end as 'roleId', GROUP_CONCAT(DISTINCT rel.role_id) as 'roles', dept.industry_code, dept.app_ver_code FROM (select su.user_id,su.DEPT_ID,su.PHONENUMBER,su.tenant_id,su.del_flag from sys_user su where su.user_type='2' and su.is_tenant_admin='0' and su.STATUS = '0') a LEFT JOIN sys_user_role rel ON a.user_id = rel.user_id left join sys_dept dept on a.dept_id = dept.dept_id WHERE a.del_flag = '0' AND (
a.user_id in
#{item}
or
(
(a.tenant_id=#{item.tenant_id} and find_in_set(rel.role_id,#{item.role_users}) and dept.industry_code=#{item.industry_code} and dept.app_ver_code=#{item.app_ver_code} ) )
) GROUP BY a.user_id union all SELECT DISTINCT a.user_id, a.DEPT_ID as org_id, a.PHONENUMBER as mobile_phone, a.tenant_id, '1' as 'roleId', GROUP_CONCAT(DISTINCT rel.role_id) as 'roles', '' as industry_code, '' as app_ver_code FROM (select su.user_id,su.DEPT_ID,su.PHONENUMBER,su.tenant_id,su.del_flag from sys_user su where su.user_type='2' and su.is_tenant_admin='1' and su.STATUS = '0') a LEFT JOIN sys_user_role rel ON a.user_id = rel.user_id WHERE a.del_flag = '0' AND (
a.user_id in
#{item}
or
(
(a.tenant_id=#{item.tenant_id} and find_in_set(rel.role_id,#{item.role_users}) ) )
) GROUP BY a.user_id

select t.userId,GROUP_CONCAT(t.deviceCodeStr) as 'deviceCodeStr',GROUP_CONCAT(t.regionCodeStr) as 'regionCodeStr'
from (

    select #{item.userId} as 'userId',GROUP_CONCAT(distinct device_code) as 'deviceCodeStr',null as 'regionCodeStr' from vm_organ_device_rel_t
    WHERE delete_flag = '0' and industry_code = #{item.industryCode} and app_ver_code = #{item.appVerCode} and tenant_id = #{item.tenantId}

        and FIND_IN_SET(dept_id,#{item.customDepts})


        and dept_id = #{item.deptId}


        and dept_id like concat(#{item.deptId},"%")

    and device_type in ('1','3','4','8','10')
    union all
    select #{item.userId} as 'userId',null as 'deviceCodeStr' ,GROUP_CONCAT(distinct county_code) as 'regionCodeStr' from vm_organ_street_rel_t
    where industry_code = #{item.industryCode} and APP_VER_CODE = #{item.appVerCode} and tenant_id = #{item.tenantId}

        and FIND_IN_SET(dept_id,#{item.customDepts})


        and dept_id = #{item.deptId}


        and dept_id like concat(#{item.deptId},"%")

    and category_code='9'

) t group by t.userId

SELECT grid_id AS 'gridId', GROUP_CONCAT(b.user_id) AS 'gridUsers' FROM bm_gridkeeper a LEFT JOIN sys_user b ON a.staff_id = b.user_id LEFT JOIN bm_grid_keeper_ref d ON a.keeper_id = d.keeper_id and d.delete_flag = '0' WHERE a.delete_flag = '0'
and d.grid_id in
#{item}

